tool-definition-structure.pattern:

# Tool definition (dictionary format)
tool_name_tool = {
    "name": "tool_name",
    "description": """
    Comprehensive description that teaches the LLM:
    - WHEN to use this tool (signal phrases, user intent)
    - HOW to use it (parameter guidance)
    - WHAT it returns (result structure)
    - EXAMPLES of common use cases

    Use this when user says "X" or asks "Y".
    """,
    "inputSchema": {
        "type": "object",
        "properties": {
            "param1": {
                "type": "string",
                "description": "Clear description of parameter purpose"
            },
            "param2": {
                "type": "integer",
                "description": "Another parameter",
                "default": 10,
                "minimum": 1,
                "maximum": 100
            }
        },
        "required": ["param1"]
    },
    "handler": tool_handler_function
}

async-handler-pattern.example-from-tools-py:

async def get_portfolio_tool_handler(
    user_id: str,
    include_prices: bool = False
) -> Dict[str, Any]:
    """
    Get user's investment portfolio holdings.

    Args:
        user_id: User identifier
        include_prices: If True, fetch current prices

    Returns:
        dict: Portfolio with holdings, total_holdings, last_updated
    """
    start_time = time.time()

    # Get config
    config = get_config()
    memories_url = config.get("AGENTIC_MEMORIES_URL", "http://host.docker.internal:8080")

    # Validate params
    if not user_id:
        return {"status": "error", "message": "Invalid user_id"}

    try:
        # Make HTTP request to backend service
        async with httpx.AsyncClient(timeout=5.0) as client:
            response = await client.get(
                f"{memories_url}/v1/portfolio",
                params={"user_id": user_id}
            )

            if response.status_code == 200:
                result = response.json()
                # ... process result
                return {"status": "success", ...}
            else:
                return {"status": "error", "message": f"HTTP {response.status_code}"}

    except httpx.TimeoutException:
        return {"status": "error", "message": "Service timed out"}
    except Exception as e:
        return {"status": "error", "message": str(e)}

error-handling-pattern.example:

try:
    # Call service
    response = await client.post(url, json=payload)

    if response.status_code == 200:
        return {"status": "success", "data": response.json()}
    else:
        # Parse error message
        try:
            error_data = response.json()
            error_msg = error_data.get("detail", f"HTTP {response.status_code}")
        except:
            error_msg = response.text or f"HTTP {response.status_code}"

        logger.error(
            "Service call failed",
            extra={"status_code": response.status_code, "error": error_msg}
        )
        return {
            "status": "error",
            "message": f"Failed: {error_msg}",
            "error_code": response.status_code
        }

except httpx.TimeoutException:
    return {"status": "error", "message": "Service timed out. Try again."}
except httpx.NetworkError:
    return {"status": "error", "message": "Service unavailable."}
except Exception as e:
    logger.error("Unexpected error", exc_info=True)
    return {"status": "error", "message": f"Unexpected error: {str(e)}"}

schema-examples.retrieve-memories-schema:
        Example of comprehensive tool schema with validation

"inputSchema": {
    "type": "object",
    "properties": {
        "user_id": {
            "type": "string",
            "description": "User identifier"
        },
        "query": {
            "type": "string",
            "description": "Search query describing decision context (e.g., 'stock investment decisions')"
        },
        "limit": {
            "type": "integer",
            "description": "Max memories to retrieve (default: 50, range: 20-1000)",
            "default": 50,
            "minimum": 20,
            "maximum": 1000
        }
    },
    "required": ["user_id", "query"]
}

schema-examples.add-holding-schema:
        Example with optional parameters and enums

"inputSchema": {
    "type": "object",
    "properties": {
        "user_id": {"type": "string", "description": "User identifier"},
        "ticker": {
            "type": "string",
            "description": "Stock ticker (e.g., 'AAPL', 'GOOGL'). Normalized to uppercase."
        },
        "shares": {
            "type": "number",
            "description": "Number of shares owned"
        },
        "avg_price": {
            "type": "number",
            "description": "Average purchase price per share in USD"
        }
    },
    "required": ["user_id", "ticker"]
}
